<?php
namespace App\Filament\Admin\Resources\Users;
use App\Filament\Admin\Resources\Users\Pages;use App\Models\User;use BackedEnum;use Filament\Actions;use Filament\Forms;use Filament\Resources\Resource;use Filament\Schemas\Schema;use Filament\Support\Icons\Heroicon;use Filament\Tables;use Filament\Tables\Table;use Illuminate\Support\Facades\Hash;
final class UserResource extends Resource{
protected static ?string$model=User::class;protected static string|BackedEnum|null$navigationIcon=Heroicon::OutlinedUsers;protected static ?string$navigationLabel='Platform users';protected static ?int$navigationSort=20;
public static function form(Schema$s):Schema{return$s->components([\Filament\Schemas\Components\Section::make('Identity')->columns(2)->schema([Forms\Components\TextInput::make('full_name')->required()->maxLength(120),Forms\Components\TextInput::make('phone_e164')->required()->tel()->regex('/^\+[1-9]\d{7,14}$/')->unique(ignoreRecord:true),Forms\Components\TextInput::make('email')->email()->maxLength(190)->unique(ignoreRecord:true),Forms\Components\Select::make('locale')->options(['en'=>'English','fr'=>'Français'])->required()->native(false)]),\Filament\Schemas\Components\Section::make('Account security')->columns(2)->schema([Forms\Components\Select::make('status')->options(['PENDING_VERIFICATION'=>'Pending verification','ACTIVE'=>'Active','SUSPENDED'=>'Suspended','LOCKED'=>'Locked'])->required()->native(false),Forms\Components\TextInput::make('password')->password()->revealable()->minLength(12)->dehydrateStateUsing(fn($state)=>filled($state)?Hash::make($state):null)->dehydrated(fn($state)=>filled($state))->required(fn(string$operation)=>$operation==='create')])]);}
public static function table(Table$t):Table{return$t->columns([Tables\Columns\TextColumn::make('full_name')->searchable()->sortable(),Tables\Columns\TextColumn::make('email')->searchable()->copyable(),Tables\Columns\TextColumn::make('phone_e164')->label('Phone')->searchable(),Tables\Columns\TextColumn::make('status')->badge()->color(fn(string$state)=>match($state){'ACTIVE'=>'success','PENDING_VERIFICATION'=>'warning','SUSPENDED','LOCKED'=>'danger',default=>'gray'}),Tables\Columns\TextColumn::make('locale')->badge(),Tables\Columns\TextColumn::make('created_at')->dateTime()->sortable()])->filters([Tables\Filters\SelectFilter::make('status')->options(['ACTIVE'=>'Active','PENDING_VERIFICATION'=>'Pending','SUSPENDED'=>'Suspended','LOCKED'=>'Locked'])])->recordActions([Actions\ViewAction::make(),Actions\EditAction::make()])->toolbarActions([Actions\CreateAction::make()])->emptyStateHeading('No platform users')->emptyStateDescription('Create a verified administrative user and assign membership separately.')->emptyStateIcon(Heroicon::OutlinedUsers);}
public static function getPages():array{return['index'=>Pages\ListUsers::route('/'),'create'=>Pages\CreateUser::route('/create'),'view'=>Pages\ViewUser::route('/{record}'),'edit'=>Pages\EditUser::route('/{record}/edit')];}}
